    if path is None:
        return None
    candidates: List[Path] = []
    if path.is_absolute():
        candidates.append(path)
    else:
        for base in bases:
            candidates.append((base / path).expanduser())
    for candidate in candidates:
        resolved = candidate.resolve()
        if resolved.exists():
            return resolved
    return candidates[0].resolve()


